from solution import allocate


def test_basic():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_zero_weight():
    assert allocate(5, [1, 0, 1]) == [3, 0, 2]


def test_negative():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]


def test_all_zero_raises():
    try:
        allocate(10, [0, 0])
    except ValueError:
        return
    assert False


def test_empty_weights():
    # all() of empty is True -> ValueError
    try:
        allocate(10, [])
    except ValueError:
        return
    assert False


def test_zero_total():
    assert allocate(0, [1, 2]) == [0, 0]


def test_large_precision():
    total = 10**18 + 1
    w = [1, 1, 1]
    r = allocate(total, w)
    assert sum(r) == total
    assert r == [333333333333333334, 333333333333333334, 333333333333333333]


def test_large_ties_exact():
    total = 10**17 + 3
    w = [3, 3, 3, 3]
    r = allocate(total, w)
    assert sum(r) == total
    assert r == [25000000000000001, 25000000000000001, 25000000000000001, 25000000000000000]


def test_float_remainder_misorder():
    # remainders 1/3 vs 1/3 exactly tie; float may differ
    r = allocate(10**15 + 1, [1, 2, 1, 2, 1, 2, 1, 2, 1, 2, 1, 2])
    assert sum(r) == 10**15 + 1


def test_tie_earlier_first():
    assert allocate(1, [1, 1]) == [1, 0]
    assert allocate(2, [1, 1, 1]) == [1, 1, 0]


def test_big_weights_exact():
    # shares: total*w/sum with huge values
    total = 10**20
    w = [10**20 + 1, 10**20 + 2, 10**20 + 3]
    r = allocate(total, w)
    assert sum(r) == total
    s = sum(w)
    for p, x in zip(r, w):
        assert abs(p - total * x // s) <= 1

