from solution import allocate


def test_example_equal():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


def test_example_zero_weight():
    assert allocate(5, [1, 0, 1]) == [3, 0, 2]


def test_negative_total():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]


def test_all_zero_raises():
    try:
        allocate(10, [0, 0])
    except ValueError:
        return
    assert False


def test_empty_weights_raises():
    try:
        allocate(10, [])
    except ValueError:
        return
    assert False


def test_zero_total():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]


def test_zero_total_zero_weights_raises():
    try:
        allocate(0, [0, 0])
    except ValueError:
        return
    assert False


def test_ties_earlier():
    assert allocate(2, [1, 1, 1]) == [1, 1, 0]


def test_largest_remainder_not_first():
    # shares: 10*1/6=1.67, 10*1/6=1.67, 10*4/6=6.67 -> floors 1,1,6 leftover 2
    # remainders equal -> first two get it
    assert allocate(10, [1, 1, 4]) == [2, 2, 6]


def test_remainder_ordering():
    # total 10, weights [3,3,4] sum 10 -> exact
    assert allocate(10, [3, 3, 4]) == [3, 3, 4]
    # total 7, weights [1,2,4]: shares 1, 2, 4 exact
    assert allocate(7, [1, 2, 4]) == [1, 2, 4]
    # total 5, weights [2,3,5]: 1,1.5,2.5 -> floors 1,1,2 leftover 1 -> tie, earlier (idx1)
    assert allocate(5, [2, 3, 5]) == [1, 2, 2]


def test_sum_exact_large():
    w = [3, 7, 11, 0, 13]
    for t in [1, 99, 12345, -12345, 10**15 + 7]:
        r = allocate(t, w)
        assert sum(r) == t
        assert r[3] == 0


def test_single_weight():
    assert allocate(-7, [5]) == [-7]


def test_negative_tie():
    assert allocate(-2, [1, 1, 1]) == [-1, -1, 0]


def test_zero_weight_not_given_leftover():
    assert allocate(1, [0, 1, 1]) == [0, 1, 0]
